def carry_over(apps, schema_editor):
    """What was written before: a payout was written down when it was paid,
    so each is paid, up to its day; and a line that takes back names the
    line it takes from - the one of the payment it reverses, or the order's
    first of the same affiliate and basis."""
    Payout = apps.get_model("affiliates", "AffiliatePayout")
    Commission = apps.get_model("affiliates", "Commission")
    for payout in Payout.objects.all():
        payout.state, payout.created = "paid", payout.paid_at or payout.created
        payout.until = (payout.paid_at or payout.created).date()
        payout.save(update_fields=["state", "created", "until"])
    for line in Commission.objects.filter(state="reversal", reverses__isnull=True).select_related("payment"):
        earned = Commission.objects.filter(order_id=line.order_id, affiliate_id=line.affiliate_id, basis=line.basis).exclude(state="reversal").order_by("id")
        exact = earned.filter(payment__provider_transaction=line.payment.reverses).first() if line.payment.reverses else None
        line.reverses = exact or earned.first()
        if line.reverses is not None:
            line.save(update_fields=["reverses"])


